	}
	if manifest.Sources.Sessions == nil && (len(manifest.Sessions) > 0 || manifest.TranscriptMode != "" || manifest.CheckpointsScanned > 0) {
		manifest.Sources.Sessions = sessionSourceFromExport(*manifest)
	}
